document.addEventListener('change',e=>{const id=e.target.id;if(['filter-status','filter-type','filter-service'].includes(id)){if(id==='filter-status')filterStatus=e.target.value;if(id==='filter-type')filterType=e.target.value;if(id==='filter-service')filterService=e.target.value;pageIndex=1;document.getElementById('table-results').innerHTML=table(filtered(),15,true);}if(e.target.name==='services'&&page==='services'){{capture(document.getElementById('services-form'));document.getElementById('advanced-services').outerHTML=advancedServices();}}if(e.target.name==='applicant_type'&&page==='profile'){capture(document.getElementById('profile-form'));render();}if(e.target.dataset.preference){if(!demo){const input=e.target;const preferences=Object.fromEntries([...document.querySelectorAll('[data-preference]')].map(field=>[field.dataset.preference,field.checked]));input.disabled=true;fetch(window.LingualsPaths.app('portal/preferences'),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':config.csrf},body:JSON.stringify(preferences)}).then(async response=>{const out=await response.json();if(!response.ok)throw Error(Object.values(out.errors||{}).flat().join(' ')||'Preferences could not be saved.');toast(out.message);}).catch(error=>{input.checked=!input.checked;toast(error.message);}).finally(()=>input.disabled=false);return;}notifications[e.target.dataset.preference]=e.target.checked;save();toast('Preview preference saved.');}});
